      const __m256d v3 = _mm256_loadu_pd(iim + j + 1 * NR);
      const __m256d v4 = _mm256_loadu_pd(tw + 0 * ns + k);
      const __m256d v5 = _mm256_loadu_pd(tw + 1 * ns + k);
      const __m256d t0 = _mm256_mul_pd(v3, v5);
      const __m256d t1 = _mm256_fmsub_pd(v2, v4, t0);
      const __m256d t2 = _mm256_add_pd(t1, v0);
      const __m256d t3 = _mm256_mul_pd(v2, v5);
      const __m256d t4 = _mm256_fmadd_pd(v3, v4, t3);
      const __m256d t5 = _mm256_add_pd(t4, v1);
      const __m256d t6 = _mm256_sub_pd(v0, t1);
      const __m256d t7 = _mm256_sub_pd(v1, t4);
      _mm256_storeu_pd(out + 2 * (o + 0 * ns), lf4_ilo(t2, t5));
      _mm256_storeu_pd(out + 2 * (o + 0 * ns) + 4, lf4_ihi(t2, t5));
      _mm256_storeu_pd(out + 2 * (o + 1 * ns), lf4_ilo(t6, t7));
